import { ZimmQuantityStepper } from 'app/components/ui-kits/molecules/zimmQuantityStepper/zimmQuantityStepper.css';
export const components = {
  Button,
  ZimmButtonLabel,
  ZimmFooter,
  ZimmFooterNavColumn,
  ZimmFooterBottomBar,
  ZimmModal,
  ZimmDrawer,
  ZimmSubscribeModal,
  ZimmSubscribeSection,
  ZimmPdpDrawer,
  ZimmContactIconRow,
  ZimmTabs,
  Header,
  ListMenu,
  ZimmDrawerMenu,
  ZimmNavItem,
  ZimmTextInput,
  ZimmHeaderLeftBar,
  ZimmHeaderRightBar,
  ZimmMegaMenuContent,
  ZimmSearchInput,
  ZimmProductContent,
  ZimmProductDescription,
  ZimmProductPrice,
  ZimmProductStyleCode,
  ZimmProductMeta,
  ZimmProductName,
  ZimmProductModelInfo,
  ZimmDropdown,
  ZimmDropdownItem,
  ZimmColourSwatch,
  ZimmColourSwatchGroup,
  ZimmProductGallery,
  ZimmGalleryOverlay,
  ZimmMediaTile,
  ZimmSlideIndicator,
  ZimmSizeChip,
  ZimmSizeChipGroup,
  ZimmProductCardMedia,
  ZimmProductCardContent,
  ZimmProductCard,
  ZimmLink,
  ZimmSizeSelector,
  ZimmSocialButton,
  ZimmAuthDrawerContent,
  ZimmBadge,
  ZimmProductBadges,
  ZimmWishlistBadge,
  ZimmCartItem,
  ZimmCartItemVariant,
  ZimmCartDrawer,
  ZimmQuantityStepper,
};

// Source: Zimmermann Design System 2026 (Handover tokens/colors.css).
// Brand primitive and semantic alias colour tokens. The alias tier below
// references the primitive tier via plain object lookups (`grey[900]`)
// rather than retyping each hex value a second time.

const grey = {
  black: 'black',
  900: '#191919',
  800: '#282828',
  700: '#454545',
  600: '#666666',
  500: '#707070',
  300: '#969696',
  200: '#d1d1d1',
  100: '#e6e6e6',
  white: '#ffffff',
};

const ivory = {
  400: '#f2e9e0',
  300: '#fbf5ef',
  200: '#f6f4f1',
  100: '#f9f8f6',
};

