1	import React, { forwardRef, type CSSProperties } from 'react';
2	import { chakra, useStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
3	import { Link as RouterLink } from 'react-router-dom';
4	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
5	import { isSafeHref, isInternalHref, buildSafeHref } from 'app/utils/safeHref';
6	import { GROW_UNDERLINE_SX } from './zimmNavItem.css';
7	
8	// Allowlist guards against javascript:/data:/vbscript: URIs from CMS-sourced hrefs (XSS vector).
9	// A single leading / is a same-origin path. // is protocol-relative and resolves off-origin,
10	// so it is excluded here and must arrive as an explicit https: URL instead.
11	// isInternalHref (app/utils/safeHref.ts) decides which of those safe hrefs also needs
12	// useMultiSite()'s buildUrl() below — see that function's own doc comment for the full
13	// reasoning. Shared with useSafeHref (app/hooks/useSafeHref.ts) and ZimmLink, rather than each
14	// re-deriving the same classification independently.
15	
16	const ChakraRouterLink = chakra(RouterLink);
17	
18	type ZimmNavItemProps = {
19	  /** Visible label text */
20	  label: string;
21	  /**
22	   * Link destination. When omitted the item renders as a `<button>` with no navigation
23	   * side-effects — no fragment scroll, no redirect — so placeholder items are safe until
24	   * real hrefs are sourced from Contentful or the routing layer.
