import { describe, test, expect } from 'vitest';
import { ZimmBadge } from './zimmBadge.css';

/**
 * index.test.tsx mocks useMultiStyleConfig globally, so this recipe's own object shape is never
 * exercised by any shipped component test — these assertions are the only thing that actually
 * reads it. Same rationale as zimmSizeChipGroup.css.test.ts (guards against a values-only
 * regression that a mocked component test can't see).
 */
describe('ZimmBadge — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmBadge.baseStyle);
    expect(parts.sort()).toEqual([...ZimmBadge.parts].sort());
  });

  test('link hover swaps the border colour and recolours the nested label', () => {
    const { link } = ZimmBadge.baseStyle;
    const hover = (link as Record<string, unknown>)._hover as Record<string, unknown>;
    expect(hover.borderColor).toBe('var(--zimm-color-action-primary-bg-hover)');
    expect((hover['.zimm-badge-label'] as Record<string, unknown>).color).toBe(
      'var(--zimm-color-action-secondary-text-disabled)',
    );
  });

  test('label composes the confirmed Input-label typography from existing primitives', () => {
    const { label } = ZimmBadge.baseStyle;
    const l = label as Record<string, unknown>;
    expect(l.fontSize).toBe('var(--zimm-font-size-4xs)');
    expect(l.lineHeight).toBe('var(--zimm-font-lineheight-2xs)');
    expect(l.fontWeight).toBe('var(--zimm-font-weight-medium)');
    expect(l.letterSpacing).toBe('var(--zimm-font-letterspacing-sm)');
    expect(l.textTransform).toBe('uppercase');
  });

  test('link uses the confirmed white background and default border tokens', () => {
    const { link } = ZimmBadge.baseStyle;
    const l = link as Record<string, unknown>;
    expect(l.backgroundColor).toBe('var(--zimm-color-bg-07)');
    expect(l.border).toBe('var(--zimm-border-width-default) solid var(--zimm-color-border-focus)');
  });

  test("staticBox shares link's visual box but carries no hover affordance", () => {
    // CodeRabbit finding (SFCC-132 review): a non-interactive badge must not visually react to
    // a pointer resting on it as though it were clickable.
    const { link, staticBox } = ZimmBadge.baseStyle;
    const l = link as Record<string, unknown>;
    const s = staticBox as Record<string, unknown>;
    expect(s._hover).toBeUndefined();
    expect(s.border).toBe(l.border);
    expect(s.backgroundColor).toBe(l.backgroundColor);
    expect(s.padding).toBe(l.padding);
  });

  test('link and staticBox never shrink below their label’s natural width', () => {
    // Regression guard: without this, a long label in a nowrap row shrinks the box while the
    // label (already flexShrink:0) refuses to shrink, so the text spills past the border.
    const { link, staticBox } = ZimmBadge.baseStyle;
    expect((link as Record<string, unknown>).flexShrink).toBe(0);
    expect((staticBox as Record<string, unknown>).flexShrink).toBe(0);
  });
});

